// Media queries, as constants: a media query cannot read a CSS variable, so the breakpoints are
// written into the queries here. Use them as keys: `{ [media.belowPhone]: ... }`.
export const media = stylex.defineConsts({
  belowPhone: "@media (width < 40rem)",
  fromPhone: "@media (width >= 40rem)",
  belowTablet: "@media (width < 48rem)",
  fromTablet: "@media (width >= 48rem)",
  belowSidebar: "@media (width < 64rem)",
  fromSidebar: "@media (width >= 64rem)",
  belowRail: "@media (width < 84rem)",
  fromRail: "@media (width >= 84rem)",
  hover: "@media (hover: hover) and (pointer: fine)",
  coarse: "@media (pointer: coarse)",
  typing: "@media (width < 40rem), (pointer: coarse)",
  reduced: "@media (prefers-reduced-motion: reduce)",
  forced: "@media (forced-colors: active)",
  noScript: "@media (scripting: none)",
  script: "@media (scripting: enabled)",
});
